     Surprise(92, 9, "أجمل عشر لحظات", "اجمعوا عشر لحظات حقيقية من المشروع، وكل واحد يختار أجمل لحظة عنده."),
     Surprise(93, 9, "تسجيل محمود", "سجّل بصوتك إيه اللي اتعلمته عن الاء خلال الرحلة."),
     Surprise(94, 9, "أنتِ مش صدفة عابرة", "اكتب رسالة تقدير عن أثر وجودها في حياتك من غير مبالغة أو ضغط."),
     Surprise(95, 9, "حاجات نعيشها سوا", "اكتبوا قائمة بتجارب واقعية تتمنوا تعيشوها معًا."),
     Surprise(96, 9, "سؤال من القلب", "اسألها: إيه أكتر حاجة نفسك أفضل فاكرها عنك؟"),
     Surprise(97, 9, "تصميم العوالم", "صمم لوحة تجمع رموز العوالم العشرة."),
     Surprise(98, 9, "خطاب محمود", "اكتب خطابًا شخصيًا بخطك أو بصورة ورقة مكتوبة بخط اليد."),
     Surprise(99, 9, "آخر لغز", "اللغز: إيه الحاجة اللي بتكبر كل ما اتقسمت بين اتنين؟ الإجابة: الذكريات الحلوة."),
     Surprise(100, 9, "لسه الحكاية بتبدأ", "يا لوليتا، خلصنا مية مفاجأة، لكن أجمل حاجة مش عدد الرسائل؛ أجمل حاجة كل لحظة حقيقية عشناها وإحنا بنتعرف على بعض أكتر. أتمنى نفضل نختار الحنية والصدق كل يوم ❤️")
)
